VERSION = "0.7.987"   # stamped by build.py (plugins/shared/version.py), as the header's

# The plugin's own config keys, and its whole default config: Orca's "Restore defaults"
# writes this back as the stored config, so a default listing every setting would pin
# those users to today's defaults for good. Every other key is a setting from options.json, the
# schema every plugin dialog is built from (mode, gap, threshold, padStyle, cutout,
# sway.on, ...), in the engine's units: a percent setting is value / 100, as
# coverage 0.5 always was here. They go to the engine through host_options, which
# checks each one, so a typo or a bad value fails the slice with the engine's own
# message rather than quietly printing default fins.
_DEFAULTS = {
    "enabled": True,
    "apply_to": "no-supports",   # "no-supports" | "all"
}
# Older configs' names: tine_density is tineDensity; bed_pad false is padStyle "off".
_ALIASES = {"tine_density": "tineDensity"}

# ---------------------------------------------------------------------------------
# Engine
# ---------------------------------------------------------------------------------
# host_engine() starts V8 with the bundle, host_compute() runs it on a soup
# --- inlined from plugins/shared/py/supportfins_host.py ---
"""Support Fins -- shared Python host for the plugins that run the engine in V8.

Every Python plugin that runs the website's engine in mini-racer (Orca today; Cura
and FreeCAD next) starts V8 and moves triangles across the same way, so that code
lives here once instead of in each plugin. Nothing here knows about fins: the
geometry is the bundle's (plugins/shared/bundle.py), and a plugin's own code only
reads the host's mesh and adds the result back.

    ctx = host_engine(ENGINE_JS)                  # once per process
    fins, stats = host_compute(ctx, soup, {"layerHeight": 0.2, "coverage": 0.5})
    options = host_options(ctx, dialog_values)    # a settings dialog's values (options.json)

How each plugin gets this file:
  Orca     inlined into the single-file plugin by plugins/orca/build.py
  others   copied next to the plugin by its build and imported

Needs numpy and mini-racer (py_mini_racer) in the host's Python.
"""
import atexit
import base64
import json
import math
import os
import sys

_host_ctx = None


def host_engine(js_source, vendor_dir=None, jit=None):
    """The one V8 context for this process, with the engine bundle loaded.

    js_source   the bundle's text (global SupportFinsEngine)
    vendor_dir  folder holding a vendored py_mini_racer/ package, for hosts that can't
                pip-install it (Cura). Under a PyInstaller app mini-racer looks for its
                library in sys._MEIPASS, the app's own bundle, and importlib.resources
                can't open files from a plugin folder there either (both seen in Cura
                5.13). Pointing _MEIPASS at vendor_dir while V8 starts fixes both.

    jit         None (default): V8 runs --jitless on macOS: mini-racer's JIT hits SIGTRAP
                there in a hardened app that refuses JIT memory (lessons from the first
                Orca spike). True: a host whose macOS app allows JIT (Blender is signed
                with com.apple.security.cs.allow-jit) keeps it -- jitless is ~25x slower
                on a big part (75k triangles: 80 s vs 3 s).
    """
    global _host_ctx
    if _host_ctx is None:
        from py_mini_racer import MiniRacer, init_mini_racer
        flags = ["--single-threaded"]
        if sys.platform == "darwin" and not jit:
            flags.append("--jitless")
        missing = object()
        saved = getattr(sys, "_MEIPASS", missing)
        if vendor_dir is not None:
            sys._MEIPASS = os.fspath(vendor_dir)
        try:
            init_mini_racer(flags=flags, ignore_duplicate_init=True)
        finally:
            if vendor_dir is not None:
                if saved is missing:
                    del sys._MEIPASS
                else:
                    sys._MEIPASS = saved
        ctx = MiniRacer()
        ctx.eval(js_source)
        # mini-racer never tears V8 down by itself: without an explicit close(), the
        # interpreter hangs forever at exit (seen in pytest on macOS, any V8 flags).
        atexit.register(ctx.close)
        _host_ctx = ctx
    return _host_ctx


def host_compute(ctx, soup, options):
    """Run the engine on a posed part.

    soup     (M,3,3) triangles, mm, z up, in whatever frame the caller likes. Kept
             float64 on the way in: rounding to float32 can flip a borderline tine
             (plugins/shared/ENGINE-SENSITIVITY.md).
    options  engine options by their engine names (layerHeight, coverage, ...);
             anything left out takes the engine's default (fins_entry.js).
    Returns (fins (K,3,3) float64 in the SAME frame as `soup`, stats dict).
    """
    fins, stats, _, _, _ = host_compute_pieces(ctx, soup, options)
    return fins, stats


def host_compute_pieces(ctx, soup, options):
    """host_compute, plus what each fin is, for hosts that show one object per fin.

    Returns (fins, stats, pieces, over_faces, small_faces):
      pieces      [{"id", "kind", "ranges": [[first, end), ...]}]: triangle ranges of
                  `fins`; kind "prop" (a wall), "wedge", "sway", "pad", ... Every
                  triangle is in exactly one piece (fins_entry.js computeFins).
      over_faces  indices of faces of `soup` in the overhangs the engine supports
                  (the site paints them red)
      small_faces past the threshold in area-based slivers or small-hole ceilings
                  left for bridging (the site's amber after generation): show them
                  too -- an overhang nothing holds isn't hidden
    """
    import numpy as np  # here, not at the top: Orca reports a failed numpy install itself
    raw = ctx.call("SupportFinsEngine.computeFinsB64", _soup_b64(soup), json.dumps(options))
    out = json.loads(raw)
    return (_unseat(out), out["stats"], out["pieces"],
            np.array(out["overFaces"], dtype=np.int64), np.array(out["smallFaces"], dtype=np.int64))


def host_draw_wall(ctx, soup, a, b, options):
    """One hand-drawn wall from a to b (Draw mode; draw_entry.js drawWall).

    soup, options  as for host_compute (the same part and options as the fins next to it)
    a, b           the wall's ends, (x, y, z) in soup's frame -- where the clicks hit
    Returns (triangles (K,3,3) float64 in soup's frame, stats {length, height, tines,
    partAttached}),
    or (None, reason) when the engine can't build it -- the site's words, for the user.
    """
    ends = [[float(v) for v in p] for p in (a, b)]
    if not all(len(p) == 3 and all(math.isfinite(v) for v in p) for p in ends):
        raise ValueError(f"wall ends must be two finite (x, y, z) points, got {a!r}, {b!r}")
    raw = ctx.call("SupportFinsEngine.drawWallB64", _soup_b64(soup),
                   json.dumps(ends[0]), json.dumps(ends[1]), json.dumps(options))
    out = json.loads(raw)
    if not out["ok"]:
        return None, out["reason"]
    return _unseat(out), out["stats"]


def _soup_b64(soup):
    import numpy as np
    soup = np.ascontiguousarray(soup, dtype=np.float64)
    return base64.b64encode(soup.tobytes()).decode("ascii")


def _unseat(out):
    """The engine's seated float32 triangles, back in the caller's frame, float64."""
    import numpy as np
    seated = np.frombuffer(base64.b64decode(out["triangles"]), dtype=np.float32)
    seated = seated.astype(np.float64).reshape(-1, 3, 3)
    off = out["offset"]  # seated = input + offset
    return seated - np.array([off["x"], off["y"], off["z"]], dtype=np.float64)


def host_schema(ctx):
    """options.json, the settings a plugin dialog is built from (as bundled)."""
    return json.loads(ctx.call("SupportFinsEngine.optionsSchemaJson"))


def host_options(ctx, values):
    """A dialog's {options.json key: value} -> engine options for host_compute.

    Always go through this rather than building the options by hand: it nests the
    sway keys, checks every value and refuses a bad one (a percent control sends
    value / 100; None or '' means the default). Raises on a bad value.
    """
    try:
        return json.loads(ctx.call("SupportFinsEngine.optionsFromDialogJson", json.dumps(values)))
    except Exception as e:
        raise ValueError(_js_message(e)) from None


def _js_message(e):
    """V8's error text carries the whole bundle's source after the message; keep only
    what the engine said ("coverage must be 0..1 ..."), which is what a user sees."""
    text = str(e)
    at = text.find("Error: ")
    return text[at + 7:].split("\n", 1)[0] if at >= 0 else text.split("\n", 1)[0]


def host_visible(ctx, key, values):
    """Whether the dialog shows the control for `key` given the current values."""
    return bool(ctx.call("SupportFinsEngine.optionVisibleJson", key, json.dumps(values)))


def host_report(stats):
    """The one-line result every plugin shows, from the engine's stats.

    Says what was placed, and -- quality first -- what wasn't: overhangs too shallow
    for a fin this way up, and pieces that start in mid-air. Same facts as the
    website's readout (web/ui/readout.js), shorter.
    """
    walls = stats.get("braces", 0) + stats.get("props", 0)   # tined + plain, as the site counts
    tines = stats.get("tines", 0)
    parts = [f"{walls} wall{'' if walls == 1 else 's'}, {tines} tine{'' if tines == 1 else 's'}"]
    braces = stats.get("swayBraces") or 0
    if braces:   # they hold the tall sides, not an overhang: never added to the walls
        parts[0] += f", {braces} sway brace{'' if braces == 1 else 's'}"
    holes = stats.get("smallHoleRegions") or 0
    if holes:
        parts.append(f"{holes} small-hole ceiling{'s' if holes != 1 else ''} left unsupported for bridging")
    unserved = stats.get("unserved") or 0
    if unserved:
        parts.append(f"{unserved} overhang{' is' if unserved == 1 else 's are'} too shallow "
                     "for a fin this way up (tilt the part steeper)")
    floating = stats.get("floating") or 0
    if floating:
        drop = float(stats.get("floatingDrop") or 0)
        parts.append((f"one piece isn't joined to the rest: it starts {drop:.1f} mm up"
                      if floating == 1 else
                      f"{floating} pieces aren't joined to the rest: the first starts {drop:.1f} mm up")
                     + ", held only by supports")
    return "; ".join(parts)
# --- end supportfins_host ---


def _engine_ctx():
    """One V8 context per process (loading the engine costs ~3 ms).

    Started at module load (see the bottom of this section), because Orca's audit
    hook is off while plugins load but gates every file open during slicing, and V8
    reads its ICU data file when it starts.
    """
    if ENGINE_JS.startswith("__FINS_ENGINE"):
        raise RuntimeError("fin engine bundle missing -- run plugins/orca/build.py")
    return host_engine(ENGINE_JS)


if not ENGINE_JS.startswith("__FINS_ENGINE"):
    try:
        _engine_ctx()
    except Exception:  # pragma: no cover - retried (and reported) on first slice
        pass


def compute_fins(soup, layer_height, cfg, nozzle=None):
    """Run the printfins.com engine on a posed part.

    soup: (M,3,3) float64 triangles, mm, in whatever frame the caller likes.
    nozzle: the part's nozzle diameter (mm), which sizes the walls and tines; None = 0.4.
    Returns (fins (K,3,3) float64 in the SAME frame as `soup`, stats dict).
    """
    ctx = _engine_ctx()
    return host_compute(ctx, soup, engine_options(ctx, cfg, layer_height, nozzle))


def engine_options(ctx, cfg, layer_height, nozzle=None):
    """The plugin config -> checked engine options (raises ValueError on a bad key or
    value). Layer height and nozzle are always the slice's own (options.json
    hostSupplied); a nozzle of None leaves the engine's 0.4."""
    values = {k: v for k, v in cfg.items() if k not in _DEFAULTS}
    # hand-written JSON says 1 / 0 (or "1" / "0") for on / off
    for o in host_schema(ctx)["options"]:
        v = values.get(o["key"])
        if o["type"] == "bool" and not isinstance(v, bool) and str(v).strip() in ("0", "1"):
            values[o["key"]] = str(v).strip() == "1"
    for old, new in _ALIASES.items():
        if old in values:
            values.setdefault(new, values[old])
            del values[old]
    bed_pad = values.pop("bed_pad", True)
    if bed_pad is False or str(bed_pad).strip().lower() in ("0", "false", "no", "off"):
        values.setdefault("padStyle", "off")
    if "layerHeight" in values:
        raise ValueError("layerHeight is Orca's own layer height: remove it from the plugin config")
    values["layerHeight"] = float(layer_height)
    if "nozzle" in values:
        raise ValueError("nozzle is Orca's own nozzle diameter: remove it from the plugin config")
    if nozzle:
        values["nozzle"] = float(nozzle)
    return host_options(ctx, values)


def _nozzle(print_object, ctx=None):
    """The nozzle (mm) that prints this object's walls, from Orca's printer settings
    ("0.4,0.6" or a list, one per extruder; wall_filament picks, 1-based). None
    when Orca doesn't say, which keeps the engine's 0.4."""
    def val(key):
        for src in (print_object, ctx):
            try:
                v = src.config_value(key) if src is not None else None
            except Exception:
                v = None
            if v not in (None, ""):
                return v
        return None
    raw = val("nozzle_diameter")
    if raw is None:
        return None
    sizes = list(raw) if isinstance(raw, (list, tuple)) else str(raw).split(",")
    try:
        sizes = [float(s) for s in sizes]
        idx = max(0, int(val("wall_filament") or 1) - 1)
    except (TypeError, ValueError):
        return None
    if not sizes:
        return None
    size = sizes[min(idx, len(sizes) - 1)]
    return size if size > 0 else None


# ---------------------------------------------------------------------------------
# Mesh -> per-layer polygons
# ---------------------------------------------------------------------------------
# split_shells() -> slice_soup() per layer -> group_loops() into outers with holes
# --- inlined from plugins/shared/py/supportfins_slice.py ---
"""Support Fins -- shared mesh slicing: triangle soup -> per-layer polygons.

For hosts whose API takes layer polygons instead of a mesh (Orca today): split the
engine's soup into closed shells, cross-section each shell at a layer's Z, and group
the loops into outers with holes. Pure numpy, no host types; the host unions the
shells with each other and with the part itself.

    for shell in split_shells(fins):
        for outer, holes in group_loops(slice_soup(shell, z)):
            ...

How each plugin gets this file:
  Orca     inlined into the single-file plugin by plugins/orca/build.py
  others   none yet; a plugin that needs it copies it in at build time, as Cura does the host
"""
try:  # Orca installs numpy from the plugin's PEP 723 header and reports a failed install itself
    import numpy as np
except ImportError:  # pragma: no cover
    np = None

# The engine emits fins as SEPARATE closed solids (wall, tines, pad) that overlap on
# purpose -- "the slicer unions them". So: split the soup into its closed shells,
# cross-section each shell on its own (where loop nesting is well defined), and let
# the host's own union (Orca: ExPolygon.union_ex) merge shells with each other and with
# the part. Winding is never trusted: outer vs hole comes from nesting depth, and the
# host normalises orientation itself (Orca: the ExPolygon constructor).

def _vkey(v, quantum=1e-4):
    return np.round(v / quantum).astype(np.int64)


def split_shells(tris):
    """Closed shells of a triangle soup: triangles are in the same shell when they
    share an EDGE. Two solids that merely touch at a vertex (a tine tip on a wall
    corner, say) stay separate, which keeps each shell's cross-section nesting sane."""
    n = len(tris)
    if n == 0:
        return []
    _, vid = np.unique(_vkey(tris.reshape(-1, 3)), axis=0, return_inverse=True)
    vid = vid.reshape(n, 3)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    owner = {}
    for f, (a, b, c) in enumerate(vid):
        for u, v in ((a, b), (b, c), (c, a)):
            e = (u, v) if u < v else (v, u)
            g = owner.setdefault(e, f)
            if g != f:
                ra, rb = find(f), find(g)
                if ra != rb:
                    parent[rb] = ra
    roots = np.array([find(f) for f in range(n)])
    return [tris[roots == r] for r in np.unique(roots)]


PLANE_NUDGE = -1e-7  # mm


def slice_soup(tris, z, quantum=1e-6):
    """Cross-section ONE closed shell with the plane Z = z -> list of closed loops,
    each an (N,2) float64 array (orientation unspecified).

    The plane is nudged DOWN by 1e-7 mm so no vertex ever lies exactly on it. It
    matters: the engine sizes the bed pad to the layer height, so the pad's top face
    can land exactly on a layer's slice_z, and a face ON the plane is ambiguous
    (half the layer is pad). Orca's own slicer puts that layer INSIDE the solid --
    measured in an Orca 2.5 nightly: lbracket's pad top sits at z = 0.5 = slice_z of layer 3,
    and a finned STL sliced by Orca prints pad there. Nudging down gives the same
    answer, so the plugin's layers match a finned STL exactly."""
    if len(tris) == 0:
        return []
    z = z + PLANE_NUDGE
    zs = tris[:, :, 2]
    sel = (zs.min(axis=1) <= z) & (zs.max(axis=1) >= z)
    if not np.any(sel):
        return []
    t = tris[sel]
    above = (t[:, :, 2] - z) >= 0.0
    n_above = above.sum(axis=1)
    keep = (n_above == 1) | (n_above == 2)
    t, above = t[keep], above[keep]
    if len(t) == 0:
        return []
    d = t[:, :, 2] - z
    segs = []
    for p, dk, ab in zip(t, d, above):
        lone = int(np.nonzero(ab if ab.sum() == 1 else ~ab)[0][0])
        a, b = (lone + 1) % 3, (lone + 2) % 3
        segs.append((_edge_cross(p[lone], p[a], dk[lone], dk[a]),
                     _edge_cross(p[lone], p[b], dk[lone], dk[b])))
    return _chain(segs, quantum)


def _edge_cross(p0, p1, d0, d1):
    s = d0 / (d0 - d1)
    return (p0 + s * (p1 - p0))[:2]


def _chain(segs, quantum):
    """Join undirected segments into closed loops via shared endpoints."""
    key = lambda q: (round(float(q[0]) / quantum), round(float(q[1]) / quantum))
    at = {}
    for i, (p, q) in enumerate(segs):
        at.setdefault(key(p), []).append(i)
        at.setdefault(key(q), []).append(i)
    used = [False] * len(segs)
    loops = []
    for i in range(len(segs)):
        if used[i]:
            continue
        used[i] = True
        start, cur_pt = segs[i]
        loop = [start]
        start_key = key(start)
        closed = False
        for _ in range(len(segs)):
            k = key(cur_pt)
            if k == start_key:
                closed = True
                break
            loop.append(cur_pt)
            nxt = next((j for j in at.get(k, ()) if not used[j]), None)
            if nxt is None:
                break  # open chain: non-manifold input, drop it
            used[nxt] = True
            p, q = segs[nxt]
            cur_pt = q if key(p) == k else p
        if closed and len(loop) >= 3:
            loops.append(np.array(loop))
    return loops


def signed_area(loop):
    x, y = loop[:, 0], loop[:, 1]
    return 0.5 * float(np.dot(x, np.roll(y, -1)) - np.dot(y, np.roll(x, -1)))


def point_in_loop(pt, loop):
    x, y = loop[:, 0], loop[:, 1]
    xn, yn = np.roll(x, -1), np.roll(y, -1)
    cond = (y > pt[1]) != (yn > pt[1])
    with np.errstate(divide="ignore", invalid="ignore"):
        xc = (xn - x) * (pt[1] - y) / (yn - y) + x
    return bool(np.count_nonzero(cond & (pt[0] < xc)) % 2)


def group_loops(loops, min_area=1e-4):
    """Loops of one shell -> [(outer, [holes])] by nesting depth (even = outer)."""
    loops = [lp for lp in loops if abs(signed_area(lp)) >= min_area]
    n = len(loops)
    contains = [[j for j in range(n) if j != i and point_in_loop(loops[i][0], loops[j])]
                for i in range(n)]
    depth = [len(c) for c in contains]
    outers = [i for i in range(n) if depth[i] % 2 == 0]
    groups = {i: [] for i in outers}
    for i in range(n):
        if depth[i] % 2 == 1:
            # its outer is the container exactly one level up
            parent = next((j for j in contains[i] if depth[j] == depth[i] - 1), None)
            if parent is not None:
                groups[parent].append(loops[i])
    return [(loops[i], groups[i]) for i in outers]
# --- end supportfins_slice ---


# ---------------------------------------------------------------------------------
# Print frame -> Orca's slice frame
# ---------------------------------------------------------------------------------
class SliceFrame:
    """Affine map from the print-frame (mm, object bottom at z=0) to slice coords.

    Orca slices each object in its own XY frame, in scaled integer units, and does
    not expose the centring offset directly. PrintObject.bounding_box() does give
    the sliced footprint in that frame, so we calibrate: the posed part's XY
    bounding box (mm) must land exactly on it. That also absorbs XY shrinkage
    compensation, which Orca applies as a scale in the object transform.
    """

    def __init__(self, part_xy_min, part_xy_max, slice_bbox, unit):
        (bx0, by0, bx1, by1) = slice_bbox
        w_mm = part_xy_max - part_xy_min
        if w_mm[0] <= 0 or w_mm[1] <= 0:
            raise ValueError("degenerate part footprint")
        self.sx = (bx1 - bx0) / w_mm[0]
        self.sy = (by1 - by0) / w_mm[1]
        self.tx = bx0 - part_xy_min[0] * self.sx
        self.ty = by0 - part_xy_min[1] * self.sy
        nominal = 1.0 / unit
        # Shrinkage compensation is a few percent at most. Anything else means the
        # bbox isn't the footprint we think it is -- refuse rather than misplace fins.
        for s in (self.sx, self.sy):
            if not (0.9 * nominal < s < 1.1 * nominal):
                raise ValueError(f"slice frame calibration off: scale {s:.1f} vs nominal {nominal:.1f}")

    def to_scaled(self, loop):
        out = np.empty((len(loop), 2), dtype=np.int64)
        out[:, 0] = np.rint(loop[:, 0] * self.sx + self.tx)
        out[:, 1] = np.rint(loop[:, 1] * self.sy + self.ty)
        return out


# ---------------------------------------------------------------------------------
# Orca glue
# ---------------------------------------------------------------------------------
def _cfg(self):
    try:
        src = json.loads(self.get_config() or "{}")
    except (AttributeError, TypeError, ValueError):
        src = {}
    if not isinstance(src, dict):
        src = {}
    return {**_DEFAULTS, **src}   # unknown keys are kept: the engine refuses them by name


def _truthy(v):
    return str(v).strip().lower() in ("1", "true", "yes", "on")


def posed_part_soup(print_object):
    """The part as Orca slices it: model-part volumes through the object->print
    transform, as (M,3,3) float64. Modifiers, negative volumes and support
    enforcers/blockers are not part of the solid and are skipped."""
    mo = print_object.model_object()
    trafo = np.asarray(print_object.trafo(), dtype=np.float64)
    chunks = []
    for vol in mo.volumes():
        if not vol.is_model_part():
            continue
        mesh = vol.mesh()
        V = np.asarray(mesh.vertices(), dtype=np.float64)
        T = np.asarray(mesh.triangles(), dtype=np.int64)
        if len(T) == 0:
            continue
        M = trafo @ np.asarray(vol.matrix(), dtype=np.float64)
        Vh = V @ M[:3, :3].T + M[:3, 3]
        tris = Vh[T]
        if np.linalg.det(M[:3, :3]) < 0:
            # A mirrored part flips every triangle's winding; the engine reads
            # overhangs from face normals, so restore outward-facing order.
            tris = tris[:, [0, 2, 1], :]
        chunks.append(tris)
    if not chunks:
        return np.empty((0, 3, 3))
    return np.concatenate(chunks, axis=0)


def _elephant_foot(print_object):
    """(compensation mm, layers) as Orca will apply it; 0 when printing on a raft."""
    def num(key, cast, default):
        try:
            v = print_object.config_value(key)
            return cast(v) if v not in (None, "") else default
        except (TypeError, ValueError):
            return default
    if num("raft_layers", int, 0) > 0:
        return 0.0, 0
    return max(0.0, num("elefant_foot_compensation", float, 0.0)), max(1, num("elefant_foot_compensation_layers", int, 1))


def _shrink_keep_thin(expolys, delta_scaled):
    """Inward offset for elephant-foot compensation. A thin fin wall that would lose
    most of its width keeps its original outline -- Orca's own compensation also
    protects features below a minimum width rather than erasing them."""
    if delta_scaled <= 0:
        return expolys
    out = []
    for e in expolys:
        shrunk = e.offset(-delta_scaled)
        kept = sum(x.area() for x in shrunk)
        out.extend(shrunk if kept >= 0.5 * e.area() else [e])
    return out


def _bbox_overlap(a, b):
    return not (a[2] < b[0] or b[2] < a[0] or a[3] < b[1] or b[3] < a[1])


def _expoly_bbox(e):
    c = np.asarray(e.contour.as_array())
    return (c[:, 0].min(), c[:, 1].min(), c[:, 0].max(), c[:, 1].max())


def add_fins_to_layer(layer, fin_expolys):
    """Merge fin ExPolygons into the layer's first region, unioning with any part
    slice they overlap (tines are meant to fuse), then re-derive the islands."""
    regions = layer.regions()
    if not regions or not fin_expolys:
        return 0
    region = regions[0]
    existing = [(s.surface_type, s.expolygon) for s in region.slices.surfaces]
    # Copy: set()/append() below invalidate references into the live collection.
    existing = [(t, orca.host.ExPolygon(e.contour, list(e.holes))) for t, e in existing]
    boxes = [_expoly_bbox(e) for _, e in existing]
    added = 0
    for fin in fin_expolys:
        merged, mtype, mbox = fin, orca.host.SurfaceType.stInternal, _expoly_bbox(fin)
        keep, keep_boxes = [], []
        for (t, e), bb in zip(existing, boxes):
            if _bbox_overlap(bb, mbox):
                u = merged.union_ex(e)
                if len(u) == 1:          # they really overlapped: fuse, keep the part's type
                    merged, mtype, mbox = u[0], t, _expoly_bbox(u[0])
                    continue
            keep.append((t, e))
            keep_boxes.append(bb)
        existing, boxes = keep + [(mtype, merged)], keep_boxes + [mbox]
        added += 1
    by_type = {}
    for t, e in existing:
        by_type.setdefault(t, []).append(e)
    items = list(by_type.items())
    region.slices.set(items[0][1], items[0][0])
    for t, es in items[1:]:
        region.slices.append(es, t)
    layer.make_slices()
    return added


def inject_fins(print_object, cfg, layer_height, unit, log=None, nozzle=None):
    """Compute fins for one PrintObject and add them to its layers. Returns a
    short human-readable result string. If `log` is a dict it is filled with
    diagnostics (frame calibration, per-layer fin area) for the spike."""
    log = {} if log is None else log
    soup = posed_part_soup(print_object)
    if len(soup) == 0:
        return "no model-part volumes"
    zmin = soup[:, :, 2].min()
    soup = soup - np.array([0.0, 0.0, zmin])       # object bottom at z = 0, like slice_z
    fins, stats = compute_fins(soup, layer_height, cfg, nozzle)
    if len(fins) == 0:
        # Quality first: no fins can still mean overhangs left bare, so say so.
        bare = stats.get("unserved") or stats.get("floating") or stats.get("smallHoleRegions")
        return host_report(stats) if bare else "no fins needed"
    pts = soup.reshape(-1, 3)
    bbox = print_object.bounding_box()
    frame = SliceFrame(pts[:, :2].min(axis=0), pts[:, :2].max(axis=0), bbox, unit)
    log.update({
        "part_faces": int(len(soup)), "part_size_mm": (pts.max(axis=0) - pts.min(axis=0)).round(4).tolist(),
        "slice_bbox_scaled": list(bbox), "unit": unit,
        "frame_scale": [frame.sx, frame.sy], "frame_scale_vs_nominal": [frame.sx * unit, frame.sy * unit],
        "engine": stats, "fin_triangles": int(len(fins)), "layers": [],
    })
    shells = split_shells(fins)
    shell_z = [(sh[:, :, 2].min(), sh[:, :, 2].max()) for sh in shells]
    efc_mm, efc_layers = _elephant_foot(print_object)
    log["elephant_foot"] = [efc_mm, efc_layers]
    touched = 0
    for layer_id, layer in enumerate(print_object.layers()):
        z = float(layer.slice_z)
        expolys = []
        for sh, (z0, z1) in zip(shells, shell_z):
            if z < z0 or z > z1:
                continue
            for outer, holes in group_loops(slice_soup(sh, z)):
                expolys.append(orca.host.ExPolygon(frame.to_scaled(outer),
                                                   [frame.to_scaled(h) for h in holes]))
        if expolys and efc_mm > 0 and layer_id < efc_layers:
            # Orca shrinks the first layer(s) by the elephant-foot compensation at
            # slice time, BEFORE our hook runs, so the part is already compensated and
            # the fins are not. Match it (measured in an Orca 2.5 nightly: without this the first
            # layer of a finned STL and of the plugin differ by the 0.1 mm EFC).
            shrink = efc_mm - (efc_mm / efc_layers) * layer_id
            expolys = _shrink_keep_thin(expolys, int(round(shrink / unit)))
        if expolys and add_fins_to_layer(layer, expolys):
            touched += 1
            log["layers"].append([round(z, 4), round(sum(e.area() for e in expolys) * unit * unit, 4)])
    log["layers_touched"] = touched
    report = host_report(stats)   # the same line every plugin shows
    if touched == 0:   # placed, but no layer took them: the overhangs are still bare
        report += "; none of it reached a layer, so nothing was added (see support_fins_log.jsonl)"
    return report


class SupportFinsSlicing(orca.slicing.SlicingPipelineCapabilityBase):
    def get_name(self):
        return "Support Fins"

    def get_default_config(self):
        return dict(_DEFAULTS)

    def execute(self, ctx):
        if ctx.step != orca.slicing.Step.posSlice or ctx.object is None:
            return orca.ExecutionResult.success()
        cfg = _cfg(self)
        if not _truthy(cfg["enabled"]):
            return orca.ExecutionResult.success("Support Fins: disabled in plugin config")
        if np is None:
            return orca.ExecutionResult.failure(orca.PluginResult.RecoverableError,
                                                "Support Fins needs numpy (install failed?)")
        po = ctx.object
        if cfg["apply_to"] != "all" and _truthy(po.config_value("enable_support")):
            return orca.ExecutionResult.success("Support Fins: skipped (Orca supports are on for this part)")
        try:
            lh = float(po.config_value("layer_height") or ctx.config_value("layer_height") or 0.2)
        except (TypeError, ValueError):
            lh = 0.2
        nozzle = _nozzle(po, ctx)
        log = {"object_id": _safe(lambda: po.id()), "layer_height": lh, "nozzle": nozzle, "started": time.time(),
               "version": VERSION}
        try:
            msg = inject_fins(po, cfg, lh, orca.slicing.unscale(1), log, nozzle=nozzle)
        except Exception as e:  # never break a slice over fins; report and carry on
            log["error"] = f"{type(e).__name__}: {e}"
            _write_log(log)
            # a config the engine refused says so in its own words; anything else is a bug
            why = str(e) if isinstance(e, ValueError) else f"{type(e).__name__}: {e}"
            return orca.ExecutionResult.failure(orca.PluginResult.RecoverableError,
                                                f"Support Fins: {why}")
        log["result"] = msg
        log["seconds"] = round(time.time() - log["started"], 3)
        _write_log(log)
        return orca.ExecutionResult.success(f"Support Fins: {msg}")


def _safe(fn):
    try:
        return fn()
    except Exception:
        return None


def _write_log(entry):
    """Spike diagnostics: append one JSON line per sliced object next to the plugin
    (support_fins_log.jsonl). Best effort -- never fails the slice."""
    try:
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "support_fins_log.jsonl")
        with open(path, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, default=str) + "\n")
    except Exception:
        pass


@orca.plugin
class SupportFinsPlugin(orca.base):
    def register_capabilities(self):
        orca.register_capability(SupportFinsSlicing)
